#include <stdarg.h>
#include "../common/retro-games/puzzles/vendor/mosaic.c"
void fatal(const char *format,...){va_list a;va_start(a,format);vfprintf(stderr,format,a);va_end(a);fputc('\n',stderr);exit(2);}
void frontend_default_colour(frontend *f,float *out){(void)f;out[0]=out[1]=out[2]=0.9F;}
static game_params *params;
static game_state *from_id(const char *id){char *copy=dupstr(id),*p=strchr(copy,':');if(!p)fatal("Missing ID");*p++=0;params=default_params();decode_params(params,copy);const char *e=validate_params(params,true);if(!e)e=validate_desc(params,p);if(e)fatal("Original validation: %s",e);game_state *s=new_game(NULL,params,p);sfree(copy);return s;}
static game_state *step(game_state *s,const char *m){game_state *n=execute_move(s,m);if(!n)fatal("Original rejection: %s",m);free_game(s);return n;}
static unsigned colour565(float *p,int c){unsigned r=(unsigned)(p[3*c]*255+.5F),g=(unsigned)(p[3*c+1]*255+.5F),b=(unsigned)(p[3*c+2]*255+.5F);return ((r>>3)<<11)|((g>>2)<<5)|(b>>3);}
static void output(game_state *s){int n;float *p=game_colours(NULL,&n);printf("{\"w\":%d,\"h\":%d,\"status\":%d,\"cheated\":%d,\"clues_left\":%d,\"cells\":[",s->width,s->height,game_status(s),s->cheating,s->not_completed_clues);for(int i=0;i<s->width*s->height;i++){int f=s->cells_contents[i],c=f&STATE_MARKED?COL_MARKED:f&STATE_BLANK?COL_BLANK:COL_UNMARKED;printf("%s[%d,%u]",i?",":"",f,colour565(p,c));}printf("],\"clues\":[");for(int i=0;i<s->width*s->height;i++)printf("%s%d",i?",":"",s->board->actual_board[i].shown?s->board->actual_board[i].clue:-1);puts("]}");sfree(p);}
static void self_test(void){game_state *s=from_id("3x3:111111111");game_ui *ui=new_ui(s);game_drawstate *ds=game_new_drawstate(NULL,s);game_set_size(NULL,ds,params,24);char *m=interpret_move(s,ui,ds,24,24,LEFT_BUTTON);assert(!strcmp(m,"t0,0"));sfree(m);m=interpret_move(s,ui,ds,24,24,RIGHT_BUTTON);assert(!strcmp(m,"T0,0"));sfree(m);assert(interpret_move(s,ui,ds,-3,24,LEFT_BUTTON)==NULL);game_free_drawstate(NULL,ds);free_ui(ui);assert(execute_move(s,"t3,0")==NULL&&execute_move(s,"t0:0")==NULL);
 s=step(s,"t1,1");int marked,blank,total;count_around_state(s,0,0,&marked,&blank,&total);assert(marked==1&&total==4&&blank==0);s=step(s,"t0,0");assert(s->cells_contents[0]&STATE_ERROR);free_game(s);free_params(params);
 s=from_id("3x3:111111111");for(int i=0;i<9;i++){char b[24];sprintf(b,"%c%d,%d",i==4?'t':'T',i%3,i/3);s=step(s,b);}assert(game_status(s)==1&&!s->cheating&&s->not_completed_clues==0);free_game(s);free_params(params);
 puts("PASS: original Left/Right marking cycles, out-of-board pointer, invalid bounds/separator, inclusive 3x3 neighbourhood counts, overfilled clue error, nine-cell uncheated victory");}
int main(int argc,char **argv){if(argc==2&&!strcmp(argv[1],"--self-test")){self_test();return 0;}if(argc>=7&&!strcmp(argv[1],"--input")){game_state *s=from_id(argv[2]);for(int i=7;i<argc;i++)s=step(s,argv[i]);game_ui *ui=new_ui(s);game_drawstate *ds=game_new_drawstate(NULL,s);game_set_size(NULL,ds,params,atoi(argv[3]));char *m=interpret_move(s,ui,ds,atoi(argv[4]),atoi(argv[5]),!strcmp(argv[6],"R")?RIGHT_BUTTON:LEFT_BUTTON);if(!m||m==MOVE_UI_UPDATE||m==MOVE_NO_EFFECT||m==MOVE_UNUSED)fatal("Original input has no move");puts(m);sfree(m);game_free_drawstate(NULL,ds);free_ui(ui);free_game(s);free_params(params);return 0;}if(argc<2)fatal("Usage: native-oracle ID [moves]");game_state *s=from_id(argv[1]);for(int i=2;i<argc;i++)s=step(s,argv[i]);output(s);free_game(s);free_params(params);return 0;}
